"""Generate `nf3h_approved_changes.json`: the explicitly approved NF-3H change to the NF-3B kernel baseline (not a test module).

NF-3H (owner decisions DEC-217 amendment 1, 2026-11-28) retires the silent 50 Hz defaults of `compute_sliding_phasor`, `evaluate_power_channel` and
`evaluate_three_phase_power_channel`: the frequency is a required argument, so a caller that omits it fails (TypeError) instead of silently getting
50 Hz. The frozen record (`nf3b_frozen_baselines.json`, group `kernels`) documents what the silent default did; it stays historical.

The ONLY outcomes that may change are the power-kernel scenarios whose window frequency is `default` (no frequency passed); each now records
`{"raises": "TypeError"}` instead of the values the silent 50 Hz window produced. Every scenario that passes a frequency (50 and 60) must be
unchanged. Kind: `silent_default_retired`. Anything else aborts generation.

Run from `backend/`:  python tests/fixtures/nf3h_baselines/generate_nf3h_approved_changes.py
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

BACKEND = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(BACKEND))

from tests import nf3b_baseline_scenarios as scenarios  # noqa: E402
from tests import nf3c_approved_changes as approved  # noqa: E402
from tests.nf3d_diff_tools import ABSENT, structured_diff  # noqa: E402

OUT = Path(__file__).with_name("nf3h_approved_changes.json")


def main() -> None:
    baseline = json.loads((BACKEND / "tests/fixtures/nf3b_baselines/nf3b_frozen_baselines.json").read_text(encoding="utf-8"))
    expected = approved.apply_approved(baseline, "nf3b_frozen_baselines", include_nf3h=False)["kernels"]
    current = scenarios.run_kernel_scenarios()
    entries = []
    for path, before, after in structured_diff(expected, current, ("kernels",)):
        # path: kernels / power / <fsN_signalN_windowW> / (single_phase / <op> | three_phase_active) / (returns | raises)
        if len(path) < 4 or path[1] != "power" or not str(path[2]).endswith("_windowdefault"):
            raise SystemExit(f"a change outside the default-window power scenarios: {path}")
        leaf = path[-1]
        if leaf == "returns":
            if after != ABSENT:
                raise SystemExit(f"unexpected new value at {path}: {after!r}")
        elif leaf == "raises":
            if after != "TypeError":
                raise SystemExit(f"the retired default must raise TypeError, got {after!r} at {path}")
        else:
            raise SystemExit(f"UNCLASSIFIED difference: {path} {before!r} -> {after!r}")
        entries.append({"path": list(path), "before": before, "after": after, "kind": "silent_default_retired"})
    OUT.write_text(json.dumps({
        "purpose": "The approved NF-3H change to the NF-3B kernel baseline: calling a power kernel without a frequency now raises TypeError "
                   "(the silent 50 Hz default is retired). Applied after the NF-3G overlay. Generated by generate_nf3h_approved_changes.py.",
        "schema": 1,
        "kinds": ["silent_default_retired"],
        "changes": {"nf3b_frozen_baselines": entries},
    }, indent=1, sort_keys=True) + "\n", encoding="utf-8")
    print(len(entries), "entries, all silent_default_retired")


if __name__ == "__main__":
    main()
